mapper.select:
SELECT TRADE_ID as id , pp.PORTFOLIO_ID portfolioId FROM TRD_PRODUCT_DEAL TPD left join PTL_TRADE PT ON TPD.TRADE_ID = PT.BUSI_NO left join PTL_PORTFOLIO PP on PP.PORTFOLIO_ID = PT.PORTFOLIO_ID WHERE FINPROD_TYPE = #{finprodType}
and tpd.ps in ('T01','T02') and tpd.trade_status != '03' and tpd.is_cancel IS NULL
AND trade_id like '%' || #{search} || '%'
